// groupOffer is the button a group page's notice holds, or nil when it offers nothing.
func groupOffer(g groupPageView) templ.Component {
	if g.offer == nil {
		return nil
	}
	return cartOffer(*g.offer)
}

// heldText is what a cart control reads for an item the cart holds, or imports with another item.
func heldText(held heldState) string {
	switch held {
	case heldInGroup:
		return "Included with its group (in cart)"
	case heldInLibrary:
		return "Included with the library (in cart)"
	}
	return "In cart"
}

// heldShape is the shape of a cart control for an item the cart holds: on one line for In cart, and wrapping for an item
// another imports, whose longer text overflows a group's row on a narrow phone.
func heldShape(held heldState) string {
	if held == heldInGroup || held == heldInLibrary {
		return cartButtonWrapShape
	}
	return cartButtonShape
}

